-- ============================================================
-- SEED EXT 3: Módulo 15 — Gerund vs Infinitive (ex 106-205)
-- Novos tópicos: perfect gerund, sense verbs, causatives,
-- gerund after conjunctions, TOEFL complex tasks
-- ============================================================
DO $$
DECLARE cid TEXT;
BEGIN
  SELECT id INTO cid FROM contents WHERE id = 'gerund-infinitive';
  IF cid IS NULL THEN RAISE EXCEPTION 'Módulo gerund-infinitive não encontrado'; END IF;

  INSERT INTO exercises (content_id, block_number, exercise_number, type, question, answer, options, explanation, difficulty) VALUES

  -- BLOCK 31: perfect gerund (having + past participle)
  (cid,31,106,'gap_fill','She left the meeting without _____ (acknowledge) the committee''s concerns.','acknowledging',NULL,'After "without" (preposition), gerund is required.','easy'),
  (cid,31,107,'multiple_choice','What is the difference: "I regret not doing the experiment" vs "I regret not having done the experiment"?','Both express past regret; "having done" emphasizes the action is fully in the past (completed before the regret).','["They are identical in meaning","Both express past regret; ''having done'' emphasizes the action is fully in the past (completed before the regret).","''Not doing'' is incorrect","''Having done'' is more informal"]','Perfect gerund = emphasizes completion before a later time.','hard'),
  (cid,31,108,'gap_fill','_____ (complete) the survey, participants were asked to write a brief reflection.','Having completed',NULL,'"Having + past participle" = perfect gerund as adverbial. Means "after completing."','hard'),
  (cid,31,109,'multiple_choice','Which sentence uses a perfect gerund correctly?','He was accused of having falsified the data in his doctoral thesis.','["He was accused of falsifying the data (also correct — simple gerund).","He was accused of having falsified the data in his doctoral thesis.","He was accused to have falsified the data.","He was accused of having falsify the data."]','"Having falsified" = perfect gerund emphasizing completion before the accusation.','hard'),
  (cid,31,110,'gap_fill','She denied _____ (know) about the irregularities before the audit began.','having known',NULL,'"Having known" = perfect gerund after deny. The knowing occurred before the audit.','hard'),
  (cid,31,111,'multiple_choice','In academic writing, "having established the theoretical framework, the study proceeds to..." uses a perfect gerund to indicate:','The framework was established before the study proceeded — prior completed action.','["A future plan","The framework was established before the study proceeded — prior completed action.","A passive construction","A conditional statement"]','Perfect gerund (having established) = temporal sequence — prior action.','hard'),
  (cid,31,112,'gap_fill','_____ (receive) no response to three previous inquiries, the team escalated the issue to senior management.','Having received',NULL,'"Having received no response" = perfect gerund for prior completed (or failed) action.','hard'),

  -- BLOCK 32: gerund after conjunctions (before/after/while/since/when/once)
  (cid,32,113,'gap_fill','Please review the consent form before _____ (sign) it.','signing',NULL,'"Before + gerund" — preposition + gerund when subject of both clauses is the same.','easy'),
  (cid,32,114,'multiple_choice','Which sentence is correct?','After analyzing the data, the team published their findings.','["After to analyze the data, the team published their findings.","After they analyzed the data, the team published their findings (also correct — full clause).","After analyzing the data, the team published their findings.","After analyzed the data, the team published their findings."]','"After + gerund" when the subject of both clauses is the same.','medium'),
  (cid,32,115,'gap_fill','Since _____ (join) the research group, she has co-authored five papers.','joining',NULL,'"Since + gerund" = from the time of (implicit subject = she).','medium'),
  (cid,32,116,'gap_fill','Once _____ (obtain) ethical approval, the team can begin data collection.','obtaining',NULL,'"Once + gerund" = as soon as the action is complete.','medium'),
  (cid,32,117,'multiple_choice','Which sentence INCORRECTLY uses a gerund after a conjunction?','While to conduct the experiment, she discovered an anomaly.','["While conducting the experiment, she discovered an anomaly.","Before submitting the manuscript, ensure all references are accurate.","After receiving the grant, the project expanded significantly.","While to conduct the experiment, she discovered an anomaly."]','"While to conduct" = wrong. "While + gerund (conducting)."','medium'),
  (cid,32,118,'gap_fill','When _____ (write) academic essays, it is important to use hedging language appropriately.','writing',NULL,'"When + gerund" = general condition. Same subject implied.','easy'),

  -- BLOCK 33: sense verbs + object + -ing vs bare infinitive
  (cid,33,119,'multiple_choice','What is the difference: "I saw him cross the street" vs "I saw him crossing the street"?','Bare infinitive = complete action observed from start to finish; -ing = action in progress when observed.','["They are identical","Bare infinitive = complete action observed from start to finish; -ing = action in progress when observed.","Crossing is incorrect with see","Cross implies the action was very brief"]','Bare infinitive = whole event. -ing = caught mid-action.','hard'),
  (cid,33,120,'gap_fill','The lab supervisor noticed the technician _____ (use) the wrong reagent and intervened immediately. (action in progress)','using',NULL,'Sense verb (notice) + object + -ing = caught in the act (ongoing action).','medium'),
  (cid,33,121,'gap_fill','The security camera recorded the intruder _____ (enter) the building at 2 a.m. (whole event on camera)','entering / enter',NULL,'Sense verb (record) + object + -ing (action caught) OR base inf (whole event). Both possible; -ing most natural for a recorded moment.','hard'),
  (cid,33,122,'multiple_choice','Which sentence uses a sense verb correctly?','She felt the floor vibrate beneath her during the tremor.','["She felt the floor to vibrate during the tremor.","She felt the floor vibrating during the tremor (also correct — ongoing sensation).","She felt the floor vibrated during the tremor.","She felt the floor is vibrating during the tremor."]','Sense verb (feel) + object + bare infinitive = whole event. -ing = ongoing sensation. Both valid.','hard'),
  (cid,33,123,'gap_fill','He watched the experiment _____ (unfold) with growing excitement. (in progress)','unfolding',NULL,'"Watch + object + -ing" = ongoing process observed in progress.','easy'),
  (cid,33,124,'multiple_choice','The passive of "They heard the explosion shake the building" is:','The building was heard to shake.','["The building was heard shaking.","The explosion was heard shaking the building.","The building was heard to shake.","The building heard the explosion shaking."]','Passive of sense verb + bare infinitive: passive form requires to-infinitive.','hard'),

  -- BLOCK 34: causative verbs (make/let/have/get)
  (cid,34,125,'gap_fill','The supervisor made the interns _____ (redo) the entire analysis from scratch.','redo',NULL,'"Make + object + bare infinitive" = force. No "to."','medium'),
  (cid,34,126,'multiple_choice','Which causative sentence is CORRECT?','The professor let the students submit their essays one day late.','["The professor let the students to submit their essays one day late.","The professor let the students submitting their essays one day late.","The professor let the students submit their essays one day late.","The professor letted the students submit their essays late."]','"Let + object + bare infinitive" (no "to").','medium'),
  (cid,34,127,'gap_fill','The manager had the technician _____ (calibrate) all the instruments before the trial.','calibrate',NULL,'"Have + object + bare infinitive" = arrange for someone to do something.','medium'),
  (cid,34,128,'gap_fill','The consultant got the board _____ (approve) the new budget within a week.','to approve',NULL,'"Get + object + to + infinitive" (unlike make/let/have, get takes TO).','hard'),
  (cid,34,129,'multiple_choice','Which sentence uses "have + object + past participle" (causative passive) correctly?','She had her manuscript proofread by a professional editor.','["She had her manuscript to be proofread by an editor.","She had a professional editor proofread her manuscript (active causative — also correct).","She had her manuscript proofread by a professional editor.","She had proofread her manuscript by an editor."]','"Have + object + past participle" = arrange for something to be done TO the object.','hard'),
  (cid,34,130,'gap_fill','The hospital had all patient records _____ (digitize/passive causative) before the new system launched.','digitized',NULL,'"Have + object + past participle" = causative passive (someone digitized them for the hospital).','hard'),

  -- BLOCK 35: gerund vs infinitive in fixed expressions
  (cid,35,131,'gap_fill','It is no use _____ (argue) with someone who refuses to consider new evidence.','arguing',NULL,'"It is no use + gerund." Fixed expression.','medium'),
  (cid,35,132,'multiple_choice','Which fixed expression correctly uses an infinitive?','It is vital to address climate change immediately.','["It is no good to complain about the schedule.","It is worth to check the data before publishing.","It is vital to address climate change immediately.","It involves to review the literature thoroughly."]','"It is vital/important/necessary/essential + to + infinitive." "No good/worth + gerund."','medium'),
  (cid,35,133,'gap_fill','It is worth _____ (note) that the sample size in this study was unusually large.','noting',NULL,'"It is worth + gerund." "Worth noting" = worth the effort of noting.','easy'),
  (cid,35,134,'gap_fill','There is no point in _____ (debate) the merits of the theory without empirical data.','debating',NULL,'"There is no point in + gerund."','easy'),
  (cid,35,135,'multiple_choice','Which sentence uses "be used to" correctly (not "used to" for past habits)?','She is now used to working under pressure and meeting tight deadlines.','["She is now used to work under pressure.","She is now used to working under pressure and meeting tight deadlines.","She is now use to working under pressure.","She used to working under pressure."]','"Be/get used to + gerund" = accustomed to. NOT infinitive.','medium'),
  (cid,35,136,'gap_fill','The researchers look forward to _____ (present) their findings at the international symposium.','presenting',NULL,'"Look forward to + gerund" — "to" is a preposition here, not part of the infinitive.','hard'),

  -- BLOCK 36: gerund/infinitive in academic texts
  (cid,36,137,'multiple_choice','[Academic] Which sentence is most precise in academic writing?','The study aims to determine whether early intervention reduces long-term healthcare costs.','["The study is aiming at determining whether early intervention reduces costs.","The study aims to determine whether early intervention reduces long-term healthcare costs.","The study aims at determining whether early intervention reduces long-term costs (both acceptable).","The study aims determining whether early intervention reduces costs."]','"Aim + to + infinitive" for stating research objectives in academic writing.','medium'),
  (cid,36,138,'gap_fill','The paper attempts _____ (reconcile) conflicting theories by introducing a new explanatory model.','to reconcile',NULL,'"Attempt + to + infinitive" in academic writing.','easy'),
  (cid,36,139,'multiple_choice','Which sentence uses "tend" correctly in academic writing?','Qualitative studies tend to provide rich, contextual data rather than generalizable statistics.','["Qualitative studies tend providing rich, contextual data.","Qualitative studies tend on providing rich data.","Qualitative studies tend to provide rich, contextual data rather than generalizable statistics.","Qualitative studies are tended to provide rich data."]','"Tend + to + infinitive" for expressing general patterns in academic writing.','easy'),
  (cid,36,140,'gap_fill','The current methodology fails _____ (account) for the significant variation between subgroups.','to account',NULL,'"Fail + to + infinitive" = does not succeed in doing.','easy'),
  (cid,36,141,'multiple_choice','In the sentence "The authors acknowledge being influenced by earlier structuralist approaches," "being influenced" is:','A passive gerund after acknowledge (gerund-taking verb).','["A present participle","A passive gerund after acknowledge (gerund-taking verb).","A perfect gerund","An infinitive of purpose"]','"Acknowledge + gerund" = verb requiring gerund. "Being influenced" = passive gerund.','hard'),
  (cid,36,142,'gap_fill','Researchers risk _____ (overlook) important nuances when relying solely on quantitative measures.','overlooking',NULL,'"Risk + gerund" — risk something + -ing.','medium'),

  -- BLOCK 37: TOEFL Reading — gerund/infinitive discrimination
  (cid,37,143,'multiple_choice','[TOEFL Reading] "The government has pledged to reduce carbon emissions by 50% before 2030." "Pledged" is followed by an infinitive because:','Pledge requires an infinitive (a commitment about a future action).','["Gerunds always follow pledge","Pledge requires an infinitive (a commitment about a future action).","Pledged is in the past so requires to","The sentence is passive"]','"Pledge to + infinitive" = formal commitment.','medium'),
  (cid,37,144,'gap_fill','[TOEFL Reading] "Scientists are beginning _____ (understand) the full complexity of the microbiome." Best form?','to understand / understanding',NULL,'"Begin + to/gerund" — both correct; "to understand" is slightly more formal in academic writing.','medium'),
  (cid,37,145,'multiple_choice','[TOEFL Reading] "The committee recommended adopting a phased approach to implementation." "Adopting" is correct because:','Recommend requires a gerund.','["Gerunds always follow the","Recommend requires a gerund.","Adopting is a participial adjective","The sentence is about future plans"]','"Recommend + gerund" (or "recommend + that + subjunctive").','medium'),
  (cid,37,146,'gap_fill','[TOEFL Reading] "The study demonstrates that regular aerobic exercise tends _____ (improve) cardiovascular health across all age groups." Best form?','to improve',NULL,'"Tend + to + infinitive."','easy'),
  (cid,37,147,'multiple_choice','[TOEFL Reading] "Having analyzed over 10,000 samples, the team concluded that..." The perfect gerund "having analyzed" tells us:','The analysis was completed before the conclusion was reached.','["The analysis is ongoing","The team has not yet analyzed the samples","The analysis was completed before the conclusion was reached.","The analysis will be completed"]','Perfect gerund = completed action before the main clause event.','medium'),

  -- BLOCK 38: TOEFL Listening comprehension
  (cid,38,148,'multiple_choice','[TOEFL Listening] A professor says: "Students often struggle to balance working part-time with keeping up with their coursework." The two gerunds are:','Working and keeping.','["Struggle and balance","Working and keeping.","Balance and coursework","Part-time and coursework"]','"Working part-time" and "keeping up with coursework" — gerunds after "balance."','easy'),
  (cid,38,149,'gap_fill','[TOEFL Listening] A professor says: "The team managed _____ (reduce) the margin of error from 12% to under 2%." Best form?','to reduce',NULL,'"Manage + to + infinitive" = succeed in doing.','easy'),
  (cid,38,150,'multiple_choice','[TOEFL Listening] "The director suggested holding the conference in the spring." If a student reports this, the correct form is:','The director suggested holding the conference in the spring (same).','["The director suggested to hold the conference in the spring (wrong — suggest + gerund).","The director suggested holding the conference in the spring (same).","The director suggested that they hold the conference in the spring (also correct — subjunctive).","The director suggested they held the conference in the spring."]','"Suggest + gerund" OR "suggest + that + subjunctive." NOT suggest + to + infinitive.','hard'),

  -- BLOCK 39: TOEFL Speaking production
  (cid,39,151,'production','[TOEFL Speaking — 45s] A professor lectures about time management. Use: avoid + gerund, manage + infinitive, tend + to + infinitive, worth + gerund, look forward to + gerund.','',NULL,'Effective time management involves avoiding procrastination and managing to complete high-priority tasks before less urgent ones. Students who perform well academically tend to plan their study sessions in advance rather than reacting to deadlines. It is worth blocking out dedicated time for deep work, free from distractions. After a productive week, students often look forward to rewarding themselves, which reinforces positive habits.','hard'),
  (cid,39,152,'production','[TOEFL Speaking — 45s] An article says some companies make employees work overtime without extra pay. Agree or disagree. Use: make + object + bare inf, let + object + bare inf, get + object + to + inf, be used to + gerund.','',NULL,'Companies should not be permitted to make employees work overtime without compensation. Ethical organizations let employees leave when their contracted hours are completed. Management should instead get employees to adopt more efficient working practices during regular hours. While some workers may be used to working long hours in certain industries, this should not be normalized or exploited.','hard'),

  -- BLOCK 40: TOEFL Writing production
  (cid,40,153,'production','[TOEFL Writing — 150 words] Write a paragraph on "The benefits of interdisciplinary research." Use at least 6 gerund/infinitive structures across the three main types: verb+gerund, verb+infinitive, gerund as subject/complement.','',NULL,'Conducting research across multiple disciplines enables scholars to address complex problems that resist single-field approaches. Understanding the relationship between social behavior and neurological processes, for example, requires integrating insights from psychology, biology, and sociology. Interdisciplinary teams tend to generate more innovative solutions because they benefit from diverse methodological perspectives. It is worth encouraging graduate students to engage with literature outside their primary field, as this broadens their analytical toolkit. While adapting to unfamiliar disciplinary conventions can be challenging, researchers who manage to do so consistently report higher levels of intellectual engagement and greater impact. Being exposed to different epistemological frameworks also helps scholars to identify the implicit assumptions within their own field, which can lead to more rigorous and self-aware research.','hard'),
  (cid,40,154,'production','[TOEFL Writing — Error Correction] Fix all gerund/infinitive errors: "She is used to work long hours. They made her to repeat the experiment. He saw her to leave the building. Having finished to write the report, she sent it. The professor suggested to postpone the seminar."','',NULL,'used to work → used to working (be used to + gerund); made her to repeat → made her repeat (make + bare inf); saw her to leave → saw her leave (sense verb + bare inf) or saw her leaving (-ing); Having finished to write → Having finished writing (finish + gerund); suggested to postpone → suggested postponing (suggest + gerund).','hard'),
  (cid,40,155,'production','[TOEFL Writing — 200 words] Write an TOEFL-style integrated paragraph analyzing a reading and a lecture about the benefits and drawbacks of remote work. Use: tend + to, involve + -ing, require + -ing, manage + to, risk + -ing, worth + -ing, be used to + -ing.','',NULL,'The reading passage suggests that remote work tends to increase employee productivity by eliminating commute time and offering greater schedule flexibility. Working from home involves setting up a dedicated workspace and requires maintaining strict boundaries between professional and personal time. While many workers have become used to collaborating virtually, the lecture raises important concerns. Remote employees risk experiencing social isolation, which can undermine morale and long-term job satisfaction. Furthermore, managing to maintain team cohesion across digital platforms requires deliberate effort from both managers and employees. It is worth investing in regular team-building activities and virtual check-ins to mitigate these social costs. Overall, the transition to remote work offers significant advantages, but organizations that manage to balance flexibility with meaningful connection will see the most positive outcomes.','hard')

  ON CONFLICT (content_id, block_number, exercise_number) DO NOTHING;
END $$;
